// JAH demo program — Inspector assignment
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function inspector(maker, candidate){ return candidate===maker?'assign someone else — fresh eyes':'assigned'; }
check("maker inspects own", inspector('amy','amy'), "assign someone else \u2014 fresh eyes");
check("peer inspects", inspector('amy','bob'), "assigned");
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

